import gzip
from collections import Counter, defaultdict
from decimal import Decimal, InvalidOperation

paths = {
    'peaks': 'inputs/ENCFF401MQL.bed.gz',
    'motifs': 'inputs/MA0139.1.tsv.gz',
    'blacklist': 'inputs/ENCFF356LFX.bed.gz',
}
for label, path in paths.items():
    counts = Counter()
    chroms = Counter()
    bad_coords = bad_nums = 0
    widths = []
    with gzip.open(path, 'rt', newline='') as fh:
        for lineno, line in enumerate(fh, 1):
            fields = line.rstrip('\r\n').split('\t')
            counts[len(fields)] += 1
            if label == 'peaks':
                expected = 10
                if len(fields) == expected:
                    s, e = int(fields[1]), int(fields[2])
                    if s < 0 or e <= s:
                        bad_coords += 1
                    widths.append(e-s)
                    chroms[fields[0]] += 1
                    try:
                        Decimal(fields[6])
                    except InvalidOperation:
                        bad_nums += 1
            elif label == 'motifs':
                expected = 7
                if lineno > 1 and len(fields) == expected:
                    s, e = int(fields[1]), int(fields[2])
                    if s < 0 or e <= s:
                        bad_coords += 1
                    widths.append(e-s)
                    chroms[fields[0]] += 1
                    try:
                        Decimal(fields[5])
                    except InvalidOperation:
                        bad_nums += 1
                    if fields[6] not in ('+', '-'):
                        bad_nums += 1
            else:
                expected = 3
                if len(fields) == expected:
                    s, e = int(fields[1]), int(fields[2])
                    if s < 0 or e < s:
                        bad_coords += 1
                    widths.append(e-s)
                    chroms[fields[0]] += 1
    print(label, 'field_counts=', dict(counts), 'bad_coords=', bad_coords, 'bad_nums=', bad_nums)
    print('  chromosomes=', len(chroms), sorted(chroms))
    print('  width min/max=', (min(widths), max(widths)) if widths else None)

# Peak coordinate groups and ordering diagnostics.
groups = Counter()
with gzip.open(paths['peaks'], 'rt', newline='') as fh:
    for line in fh:
        x = line.rstrip('\r\n').split('\t')
        groups[(x[0], int(x[1]), int(x[2]))] += 1
print('peak coordinate groups:', len(groups))
print('records in duplicate-coordinate groups:', sum(n for n in groups.values() if n > 1))
print('largest coordinate group:', max(groups.values()))

# Check whether chromosome blocks are coordinate-sorted (not required, but useful for indexing).
for label, path, skip in [('peaks', paths['peaks'], False), ('motifs', paths['motifs'], True), ('blacklist', paths['blacklist'], False)]:
    last = {}
    unsorted_blocks = 0
    decreases = 0
    with gzip.open(path, 'rt', newline='') as fh:
        for lineno, line in enumerate(fh, 1):
            if skip and lineno == 1:
                continue
            x = line.rstrip('\r\n').split('\t')
            chrom, start = x[0], int(x[1])
            if chrom in last and start < last[chrom]:
                decreases += 1
            last[chrom] = start
    print(label, 'within-chromosome start decreases:', decreases)
